CREATE TABLE Assignment (AssignmentID INT AUTO_INCREMENT PRIMARY KEY, CourseID INT REFERENCES Course(CourseID), CreatedBy INT, Title VARCHAR(120), Description TEXT, Deadline DATE, MaxMarks INT);
CREATE TABLE Document (DocumentID INT AUTO_INCREMENT PRIMARY KEY, UploadedBy INT, Title VARCHAR(120), FileType VARCHAR(50), FilePath VARCHAR(300), UploadedOn DATETIME, AccessLevel VARCHAR(40));
CREATE TABLE Submission (SubmissionID INT AUTO_INCREMENT PRIMARY KEY, AssignmentID INT NOT NULL, StudentID INT NOT NULL, SubmittedAt DATETIME, Marks INT NULL, Comments TEXT, UNIQUE(AssignmentID,StudentID), FOREIGN KEY(AssignmentID) REFERENCES Assignment(AssignmentID), FOREIGN KEY(StudentID) REFERENCES Student(StudentID));
CREATE TABLE SubmissionDocument (SubmissionID INT, DocumentID INT, PRIMARY KEY(SubmissionID,DocumentID), FOREIGN KEY(SubmissionID) REFERENCES Submission(SubmissionID), FOREIGN KEY(DocumentID) REFERENCES Document(DocumentID));
CREATE TABLE SubmissionEvaluation (EvaluationID INT AUTO_INCREMENT PRIMARY KEY, SubmissionID INT, FacultyID INT, MarksGiven INT, Comments TEXT, EvaluatedAt DATETIME);
CREATE TABLE Attendance (AttendanceID INT AUTO_INCREMENT PRIMARY KEY, StudentID INT, CourseID INT, Status VARCHAR(20));
CREATE TABLE Timetable (TimetableID INT AUTO_INCREMENT PRIMARY KEY, CourseID INT, DayOfWeek VARCHAR(12), StartTime TIME, EndTime TIME, RoomNo VARCHAR(30));
CREATE TABLE Exam (ExamID INT PRIMARY KEY, CourseID INT, ExamType VARCHAR(20), MaxMarks INT, ExamDate DATE);
CREATE TABLE ExamResult (ExamID INT, StudentID INT, Grade VARCHAR(3), MarksObtained INT, PRIMARY KEY(ExamID,StudentID));
CREATE TABLE Feedback (StudentID INT, FacultyID INT, CourseID INT, Rating INT, Comments TEXT, CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE AnnouncementCourse (AnnouncementID INT, CourseID INT);
